local initials = {}
local function next_utf8(text, position)
    local first = text:byte(position)
    if not first then return nil, position end
    local length = first < 0x80 and 1
        or (first >= 0xC2 and first <= 0xDF and 2
            or (first >= 0xE0 and first <= 0xEF and 3
                or (first >= 0xF0 and first <= 0xF4 and 4 or 1)))
    return text:sub(position, position + length - 1), position + length
end
-- Iterate in a fixed order so polyphonic characters resolve identically on
-- every Lua runtime (table iteration order is intentionally unspecified).
for code = string.byte("a"), string.byte("z") do
    local initial = string.char(code)
    local characters = groups[initial]
    if characters then
        local position = 1
        while position <= #characters do
            local character, next_position = next_utf8(characters, position)
            if not character then break end
            initials[character] = initials[character] or initial
            position = next_position
        end
    end
end

return initials
